INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31911, 'Mark 11:10', 'Mark', 11, 10, 'مبارکه دې وي زمونږ د نیکه داود راتلونکې پاچاهي. ثنا دې وي څښتن تعالی ته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_10.mp3', '', 1761754199, 1761754199),
(31912, 'Mark 11:11', 'Mark', 11, 11, 'عیسی اورشلیم ته ورسېده او د خدای کور ته ننوت او هلته شاوخوا ټولو شیانو ته یې وکتل. خو څرنګه چې ناوخته ؤ، نو د هغو دولسو شاګردانو سره بیت‌عنیا ته لاړ. عیسی د انځر په ونې لعنت وایي (متي ۲۱‏:‌۱۸‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_11.mp3', '', 1761754199, 1761754199),
(31913, 'Mark 11:12', 'Mark', 11, 12, 'په بله ورځ کله چې عیسی او شاګردان یې د بیت‌عنیا څخه راروان وو، نو عیسی وږی شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_12.mp3', '', 1761754199, 1761754199),
(31914, 'Mark 11:13', 'Mark', 11, 13, 'هغه د لېرې نه د انځر یوه ونه ولیدله چې په پاڼو کې پټه وه، هغه ورغی چې څه انځر په کې پیدا کړي. خو کله چې هلته ورسېده، نو بې له پاڼو یې په کې بل هېڅ شی ونه موندل، ځکه چې دا د انځرو د پخېدلو موسم نه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_13.mp3', '', 1761754199, 1761754199),
(31915, 'Mark 11:14', 'Mark', 11, 14, 'نو هغې ونې ته یې وویل: «نور به هېڅوک هم هېڅکله ستا مېوه ونه خوري.» او د هغه شاګردانو واورېدل چې هغه څه وویل. عیسی د خدای د کور نه سوداګران شړي (متي ۲۱‏:‌۱۲‌‏-‌۱۷ او لوقا ۱۹‏:‌۴۵‌‏-‌۴۸ او یوحنا ۲‏:‌۱۳‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_14.mp3', '', 1761754199, 1761754199),
(31916, 'Mark 11:15', 'Mark', 11, 15, 'کله چې هغوی اورشلیم ته ورسېدل، نو عیسی د خدای کور ته ننوت او له هغه ځای څخه یې د خرڅوونکو او اخیستونکو په شړلو پیل وکړ. د صرافانو مېزونه او د کوترو خرڅوونکو چوکۍ‌ګانې یې په بل مخ واړولې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_15.mp3', '', 1761754199, 1761754199),
(31917, 'Mark 11:16', 'Mark', 11, 16, 'او چاته یې اجازه نه ورکوله چې د خدای د کور د حوېلۍ په لاره کوم شی یوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_16.mp3', '', 1761754199, 1761754199),
(31918, 'Mark 11:17', 'Mark', 11, 17, 'بیا هغه خلکو ته تعلیم ورکاوه او ویل یې: «ایا د خدای په کلام کې دا نه دي لیکل شوي: زما کور به د ټولو قومونو دپاره د دعا کور بلل کیږي خو تاسو ترې د غلو د پټېدلو ځای جوړ کړی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_17.mp3', '', 1761754199, 1761754199),
(31919, 'Mark 11:18', 'Mark', 11, 18, 'مشرانو کاهنانو او د شریعت عالمانو چې دا واورېدل، نو په دې لټه کې شول چې د عیسی د وژلو دپاره کومه لاره پیدا کړي. خو هغوی وېرېدل، ځکه چې ټول خلک د هغه تعلیم ته حیران وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_18.mp3', '', 1761754199, 1761754199),
(31920, 'Mark 11:19', 'Mark', 11, 19, 'کله چې ماښام شو، نو عیسی او شاګردان یې د ښار څخه ووتل. د انځر د ونې څخه عبرت اخیستل (متي ۲۱‏:‌۲۰‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_19.mp3', '', 1761754199, 1761754199),
(31921, 'Mark 11:20', 'Mark', 11, 20, 'بله ورځ سهار وختي کله چې هغوی په لاره تېرېدل، نو ویې لیدل چې هغه د انځر ونه له بېخه وچه شوې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_20.mp3', '', 1761754199, 1761754199),
(31922, 'Mark 11:21', 'Mark', 11, 21, 'پطروس هغه خبره رایاده کړه چې عیسی د انځر ونې ته کړې وه او ویې ویل: «استاذه! ګوره، د انځر په هغې ونې چې تا لعنت ویلی ؤ هغه وچه شوې ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_21.mp3', '', 1761754199, 1761754199),
(31923, 'Mark 11:22', 'Mark', 11, 22, 'عیسی ورته په ځواب کې وویل: «په خدای باندې ایمان ولرئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_22.mp3', '', 1761754199, 1761754199),
(31924, 'Mark 11:23', 'Mark', 11, 23, 'په یقین سره زه تاسو ته دا وایم چې که څوک ایمان ولري او په زړه کې شک ونه کړي، نو که دې غره ته ووایي چې د خپل ځای څخه پورته شه او په بحیرې کې وغورځېږه، نو همداسې به وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_23.mp3', '', 1761754199, 1761754199),
(31925, 'Mark 11:24', 'Mark', 11, 24, 'نو له دې امله زه تاسو ته وایم هرڅه چې تاسو یې په دعا کې وغواړئ، نو یقین ولرئ چې لاسته به یې راوړئ او هغه به ستاسو شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_24.mp3', '', 1761754199, 1761754199),
(31926, 'Mark 11:25', 'Mark', 11, 25, 'او هرکله چې تاسو د دعا دپاره ودرېږئ، نو که ستاسو په زړونو کې د چا په خلاف کوم څه شی وي هغه وبخښئ، ترڅو ستاسو اسماني پلار هم ستاسو ګناهونه وبخښي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_25.mp3', '', 1761754199, 1761754199),
(31927, 'Mark 11:26', 'Mark', 11, 26, '[خو که چېرې تاسو نور خلک ونه بخښئ، نو ستاسو اسماني پلار به هم ستاسو ګناهونه ونه بخښي.]» د عیسی د اختیار په هکله پوښتنه (متي ۲۱‏:‌۲۳‌‏-‌۲۷ او لوقا ۲۰‏:‌۱‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_26.mp3', '', 1761754199, 1761754199),
(31928, 'Mark 11:27', 'Mark', 11, 27, 'هغوی یوځل بیا اورشلیم ته راغلل. کله چې عیسی د خدای په کور کې ګرځېده، نو مشران کاهنان، د شریعت عالمان او د قوم مشران ورته راغلل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_27.mp3', '', 1761754199, 1761754199),
(31929, 'Mark 11:28', 'Mark', 11, 28, 'او د هغه څخه یې پوښتنه وکړه: «ته څه حق لرې چې دا کارونه کوې؟ چا تاته دا اختیار درکړی دی چې دا کارونه وکړې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_28.mp3', '', 1761754199, 1761754199),
(31930, 'Mark 11:29', 'Mark', 11, 29, 'عیسی ځواب ورکړ: «زه هم ستاسو څخه یوه پوښتنه کوم او که تاسو ځواب راکړ، نو زه به هم درته ووایم چې زه په کوم اختیار سره دا کارونه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_29.mp3', '', 1761754199, 1761754199),
(31931, 'Mark 11:30', 'Mark', 11, 30, 'د یحیی د تعمید ورکول د خدای له خوا ؤ یا د انسان له خوا؟ ځواب راکړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_30.mp3', '', 1761754199, 1761754199),
(31932, 'Mark 11:31', 'Mark', 11, 31, 'هغوی په خپل منځ کې سره بحث وکړ او ویل یې: «که چېرې ووایو چې د خدای له خوا ؤ، نو هغه به ووایي چې بیا تاسو ولې په هغه باندې ایمان رانه وړ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_31.mp3', '', 1761754199, 1761754199),
(31933, 'Mark 11:32', 'Mark', 11, 32, 'خو که ووایو چې د انسان له خوا ؤ، نو بیا به څه وشي؟» (هغوی د خلکو څخه وېرېدل، ځکه چې ټولو خلکو یحیی پیغمبر ګڼلو.)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_32.mp3', '', 1761754199, 1761754199),
(31934, 'Mark 11:33', 'Mark', 11, 33, 'نو هغوی عیسی ته په ځواب کې وویل: «مونږ نه پوهېږو.» عیسی ورته وویل: «نو زه هم تاسو ته نه وایم چې په کوم اختیار دا کارونه کوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_33.mp3', '', 1761754199, 1761754199),
(31935, 'Acts 11:1', 'Acts', 11, 1, 'په ټوله یهودیه کې رسولان او ایمانداران خبر شول چې غیریهودیانو هم د خدای پیغام منلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_1.mp3', '', 1761754199, 1761754199),
(31936, 'Acts 11:2', 'Acts', 11, 2, 'کله چې پطروس بېرته اورشلیم ته راغی، نو یوې ډلې چې د غیریهودیانو د سنتولو غوښتونکي وو په هغه باندې اعتراض وکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_2.mp3', '', 1761754199, 1761754199),
(31937, 'Acts 11:3', 'Acts', 11, 3, 'او ویل یې: «ته ولې د ناسنت شویو خلکو کور ته لاړې او د هغوی سره دې ډوډۍ هم وخوړله؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_3.mp3', '', 1761754199, 1761754199),
(31938, 'Acts 11:4', 'Acts', 11, 4, 'نو څه چې پېښ شوي وو، پطروس ټکي په ټکي هغوی ته بیان کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_4.mp3', '', 1761754199, 1761754199),
(31939, 'Acts 11:5', 'Acts', 11, 5, 'هغه وویل: «زه د یافا په ښار کې وم او دعا مې کوله چې بې‌هوشه شوم او رویا مې ولیدله چې د یو لوی دسترخوان په شان یو شی چې د څلورو څنډو څخه راځوړند ؤ او د اسمان نه د ځمکې خواته راښکته کېده او ما پورې راورسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_5.mp3', '', 1761754199, 1761754199),
(31940, 'Acts 11:6', 'Acts', 11, 6, 'کله چې ما ورته په غور سره وکتل، نو په هغه کې کورني حیوانات او وحشي ځناور، خزندې او مرغان وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_6.mp3', '', 1761754199, 1761754199),
(31941, 'Acts 11:7', 'Acts', 11, 7, 'بیا مې یو اواز واورېد چې ویل یې: ‹ای پطروسه! پاڅېږه، هغه حلال کړه او ویې خوره.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_7.mp3', '', 1761754199, 1761754199),
(31942, 'Acts 11:8', 'Acts', 11, 8, 'خو ما ورته وویل: ‹څښتنه! هېڅکله نه، ما هېڅکله هم کوم حرام یا ناپاکه شی خولې ته نه دی وروړی.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_8.mp3', '', 1761754199, 1761754199),
(31943, 'Acts 11:9', 'Acts', 11, 9, 'د اسمان څخه یوځل بیا اواز راغی چې ویل یې: ‹کوم شیان چې خدای حلال ګرځولي دي، ته یې باید حرام ونه ګڼې.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_9.mp3', '', 1761754199, 1761754199),
(31944, 'Acts 11:10', 'Acts', 11, 10, 'درې ځلې داسې وشول او بیا هغه ټول شیان بېرته اسمان ته یووړل شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_10.mp3', '', 1761754199, 1761754199),
(31945, 'Acts 11:11', 'Acts', 11, 11, 'په هماغه شېبه کې درې تنه چې د قیصریې څخه رالېږل شوي وو، هغه کور ته راورسېدل چې مونږ په کې اوسېدلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_11.mp3', '', 1761754199, 1761754199),
(31946, 'Acts 11:12', 'Acts', 11, 12, 'روح القدس راته وویل چې په دې هکله اندېښنه مه کوه چې هغوی غیریهودیان دي. بیا دا شپږ ایمانداران هم زما سره لاړل او مونږ ټول د کورنیلیوس کور ته ورننوتلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_12.mp3', '', 1761754199, 1761754199),
(31947, 'Acts 11:13', 'Acts', 11, 13, 'هغه مونږ ته وویل چې څنګه یې په خپل کور کې یوه فرښته ولیدله چې ولاړه وه او هغه ته یې وویل: ‹یو څوک یافا ته ولېږه او شمعون چې پطروس ورته ویل کیږي، راوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_13.mp3', '', 1761754199, 1761754199),
(31948, 'Acts 11:14', 'Acts', 11, 14, 'هغه به تاته یو پیغام واوروي چې د هغه په وسیله به ته او ستا ټوله کورنۍ خلاصون ومومئ.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_14.mp3', '', 1761754199, 1761754199),
(31949, 'Acts 11:15', 'Acts', 11, 15, 'کله چې ما خبرې پیل کړې، نو په هغوی باندې روح القدس نازل شو لکه څنګه چې لومړی ځل په مونږ باندې نازل شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_15.mp3', '', 1761754199, 1761754199),
(31950, 'Acts 11:16', 'Acts', 11, 16, 'بیا ماته را په یاد شول څه چې څښتن عیسی ویلي وو: ‹یحیی به په اوبو باندې د تعمید غسل ورکاوه، خو تاسو ته به په روح القدس د تعمید غسل درکول کیږي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_16.mp3', '', 1761754199, 1761754199),
(31951, 'Acts 11:17', 'Acts', 11, 17, 'که خدای هغوی ته هماغه نعمت ورکړی دی چې مونږ ته یې په هغه وخت کې راکړ چې په څښتن عیسی مسیح باندې مو ایمان راوړ، نو بیا زه څوک وم چې خدای مې د دې کار نه منع کړی وای؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_17.mp3', '', 1761754199, 1761754199),
(31952, 'Acts 11:18', 'Acts', 11, 18, 'کله چې هغوی دا خبرې واورېدلې، نو غلي پاتې شول. هغوی د خدای په ثنا او صفت کولو پیل وکړ او ویل یې: «نو بیا خدای حتی غیریهودیانو ته هم دا موقعه ورکړې ده چې توبه وباسي او تلپاتې ژوندون ولري.» د سوریې په انطاکیه کې کلیسا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_18.mp3', '', 1761754199, 1761754199),
(31953, 'Acts 11:19', 'Acts', 11, 19, 'د هغې ځورونې له امله چې د استیفان د مړینې نه وروسته پیل شوه، ځینې ایمانداران خواره واره شول او د فنیقیې، قبرس او انطاکیې پورې لاړل. هغوی خپل پیغام یوازې یهودیانو ته ورساوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_19.mp3', '', 1761754199, 1761754199),
(31954, 'Acts 11:20', 'Acts', 11, 20, 'خو د قبرس او قیروان ځینې ایمانداران چې انطاکیې ته لاړل، د یونانیانو سره یې هم خبرې وکړې او هغوی ته یې د څښتن عیسی په هکله زېری ورساوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_20.mp3', '', 1761754199, 1761754199),
(31955, 'Acts 11:21', 'Acts', 11, 21, 'د څښتن قدرت د هغوی سره ؤ او زیات شمېر خلکو ایمان راوړ او د څښتن عیسی پیروان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_21.mp3', '', 1761754199, 1761754199),
(31956, 'Acts 11:22', 'Acts', 11, 22, 'دا خبر د اورشلیم کلیسا ته ورسېد او هغوی برناباس انطاکیې ته ولېږه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts11_verse_22.mp3', '', 1761754199, 1761754199),
