(32000, 'Mark 7:4', 'Mark', 7, 4, 'کله چې به هغوی د بازار څخه راتلل، نو تر هغې پورې چې غسل به یې نه ؤ کړی، هېڅ شی به یې نه خوړل. او د نورو ډېرو رواجونو څخه به یې پیروي کوله لکه د پیالو، دېګونو او مسي لوښو وینځل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_4.mp3', '', 1761754199, 1761754199),
(32001, 'Mark 7:5', 'Mark', 7, 5, 'نو فریسیانو او د شریعت عالمانو د عیسی څخه پوښتنه وکړه: «ستا شاګردان ولې زمونږ د نیکونو په رواجونو باندې عمل نه کوي، بلکې په ناپاکو لاسونو ډوډۍ خوري؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_5.mp3', '', 1761754199, 1761754199),
(32002, 'Mark 7:6', 'Mark', 7, 6, 'عیسی ځواب ورکړ: «اشعیا نبي په حقه ؤ چې ستاسو منافقانو په هکله یې پېشګویي کوله، لکه څنګه چې هغه لیکلي وو: دا خلک په خوله زما عزت کوي، خو زړونه یې زما نه لېرې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_6.mp3', '', 1761754199, 1761754199),
(32003, 'Mark 7:7', 'Mark', 7, 7, 'د هغوی عبادت ګټه نه لري، ځکه چې هغوی د خدایي حکمونو په ځای د انساني حکمونو تعلیم ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_7.mp3', '', 1761754199, 1761754199),
(32004, 'Mark 7:8', 'Mark', 7, 8, 'نو تاسو د خدای حکمونه پریښي دي او په انساني روایتونو باندې عمل کوئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_8.mp3', '', 1761754199, 1761754199),
(32005, 'Mark 7:9', 'Mark', 7, 9, 'عیسی هغوی ته دا هم وویل: «تاسو د خدای د حکمونو د ردولو دپاره ښه لاره موندلې، ترڅو په خپلو رواجونو باندې عمل وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_9.mp3', '', 1761754199, 1761754199),
(32006, 'Mark 7:10', 'Mark', 7, 10, 'ځکه موسی ویلي دي چې د خپل مور او پلار عزت کوه او هرڅوک چې خپل مور او پلار ته ښکنځلې وکړي، باید ووژل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_10.mp3', '', 1761754199, 1761754199),
(32007, 'Mark 7:11', 'Mark', 7, 11, 'خو تاسو وایئ چې که چېرې څوک خپل مور او پلار ته ووایي چې زه ستاسو سره مرسته نه شم کولای، ځکه کوم څه چې باید تاسو ته مې درکړي وای ما نذر منلی دی چې هغه د خدای په نوم ورکړم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_11.mp3', '', 1761754199, 1761754199),
(32008, 'Mark 7:12', 'Mark', 7, 12, 'نو په دې ډول تاسو هغه نور نه پرېږدئ چې د خپل مور او پلار سره مرسته وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_12.mp3', '', 1761754199, 1761754199),
(32009, 'Mark 7:13', 'Mark', 7, 13, 'نو د خپل دود او دستور په خاطر د خدای کلام ته ارزښت نه ورکوئ. او تاسو داسې نور ډېر کارونه هم کوئ.» هغه شیان چې د انسان د ناپاکۍ سبب ګرځي (متي ۱۵‏:‌۱۰‌‏-‌۲۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_13.mp3', '', 1761754199, 1761754199),
(32010, 'Mark 7:14', 'Mark', 7, 14, 'عیسی یوځل بیا خلک راوغوښتل او ورته ویې ویل: «تاسو ټول زما خبرو ته غوږ ونیسئ او ځان ورباندې پوه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark7_verse_14.mp3', '', 1761754199, 1761754199);